package com.volna.inventory_service.entity;
import com.volna.inventory_service.enums.PurchaseOrderStatus;import jakarta.persistence.*;import java.math.BigDecimal;import java.time.LocalDateTime;import java.util.*;
@Entity @Table(name="inventory_purchase_orders") public class PurchaseOrder { @Id @GeneratedValue(strategy=GenerationType.IDENTITY)Long id;@Column(name="restaurant_id",nullable=false)UUID restaurantId;@ManyToOne(fetch=FetchType.LAZY)@JoinColumn(name="vendor_id",nullable=false)InventoryVendor vendor;@Enumerated(EnumType.STRING)@Column(nullable=false,length=30)PurchaseOrderStatus status=PurchaseOrderStatus.DRAFT;@Column(name="estimated_total",nullable=false,precision=12,scale=2)BigDecimal estimatedTotal=BigDecimal.ZERO;String notes;@Column(name="created_at",nullable=false)LocalDateTime createdAt;@OneToMany(mappedBy="purchaseOrder",cascade=CascadeType.ALL,orphanRemoval=true)List<PurchaseOrderItem> items=new ArrayList<>();@PrePersist void c(){createdAt=LocalDateTime.now();}public Long getId(){return id;}public UUID getRestaurantId(){return restaurantId;}public void setRestaurantId(UUID v){restaurantId=v;}public InventoryVendor getVendor(){return vendor;}public void setVendor(InventoryVendor v){vendor=v;}public PurchaseOrderStatus getStatus(){return status;}public void setStatus(PurchaseOrderStatus v){status=v;}public BigDecimal getEstimatedTotal(){return estimatedTotal;}public void setEstimatedTotal(BigDecimal v){estimatedTotal=v;}public String getNotes(){return notes;}public void setNotes(String v){notes=v;}public LocalDateTime getCreatedAt(){return createdAt;}public List<PurchaseOrderItem> getItems(){return items;}public void addItem(PurchaseOrderItem i){items.add(i);i.setPurchaseOrder(this);} }
